import { useMemo } from "react";
import {
  StatCard,
  PageHeader,
  EmptyState,
  StatusBadge,
} from "../../../components/common/index.jsx";
import { Q, PRESETS } from "../../../apollo/gql.js";
import { useApiQuery } from "../../../apollo/useApi.js";
import { useFacets } from "../../../components/common/EntryFilters.jsx";
import { getChapterName } from "../../../utils/helpers.js";

// ─── PA Overview ────────────────────────────────────────────────
export default function PAOverview() {
  // fetch embentries
  const {
    data: entriesData,
    loading,
    error,
    refetch,
  } = useApiQuery(Q.activities.list, {
    fields: PRESETS.activityOverview,
    variables: {
      page: 1,
      limit: 5,
    },
    fetchPolicy: "cache-and-network",
  });
  const { facets, facetLoading, facetError, refetchFacets } = useFacets();
  const entries = entriesData?.activities?.data ?? [];
  // list projects
  const {
    data: projectsData,
    loading: projectsLoading,
    error: projectsError,
    refetch: refetchProjects,
  } = useApiQuery(Q.projects.list, {
    fields: PRESETS.projectListCard,
    variables: {
      page: 1,
      limit: 5,
    },
    fetchPolicy: "cache-and-network",
  });
  const { statusCount, total } = facets;
  const stats = {
    total: total,
    SUBMITTED: 0,
    APPROVED: 0,
    REJECTED: 0,
  };
  statusCount.forEach(({ status, count }) => (stats[status] = count));

  const submittedEntries = entries.filter((e) => e.status === "SUBMITTED");

  const chapterBreakdown = useMemo(() => {
    const map = {};
    for (const e of entries) {
      const name = getChapterName(e.chapter);
      if (!name) continue;
      map[name] = (map[name] ?? 0) + 1;
    }
    return Object.entries(map).sort((a, b) => b[1] - a[1]);
  }, [entries]);

  return (
    <div className="fade-up">
      <PageHeader
        title={`Dashboard`}
        subtitle="Overview of e-MB activity in your span"
      />
      <div className="stats-grid">
        <StatCard
          icon="📋"
          number={stats.total}
          label="Total Entries"
          color="var(--blue)"
        />
        <StatCard
          icon="⏳"
          number={stats.SUBMITTED}
          label="Submitted"
          color="var(--yellow)"
        />
        <StatCard
          icon="✅"
          number={stats.APPROVED}
          label="Approved"
          color="var(--green)"
        />
        <StatCard
          icon="❌"
          number={stats.REJECTED}
          label="Rejected"
          color="var(--red)"
        />
        <StatCard icon="🏗️" number={projectsData?.projects?.PaginationMetaData?.totalDocuments} label="Projects" color="var(--purple)" />
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
        <div className="card">
          <div className="card-header">
            <span className="card-title">Submitted Entries</span>
          </div>
          {submittedEntries.map((e) => (
              <div
                key={e._id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  padding: "10px 0",
                  borderBottom: "1px solid var(--border)",
                }}
              >
                <div>
                  <div style={{ fontSize: 13, fontWeight: 600 }}>
                    {getChapterName(e.chapter) ?? "—"}
                  </div>
                  <div
                    style={{
                      fontSize: 11,
                      color: "var(--text2)",
                      marginTop: 2,
                    }}
                  >
                    {e.createdBy?.name ?? "—"} ·{" "}
                    {e.createdAt
                      ? new Date(e.createdAt).toLocaleString("en-IN")
                      : "—"}
                  </div>
                </div>
                <div style={{ textAlign: "right" }}>
                  <div
                    style={{
                      fontSize: 13,
                      color: "var(--accent)",
                      fontWeight: 600,
                    }}
                  >
                    ₹{e.lineItems?.reduce((acc, item) => acc + item.amount, 0)?.toLocaleString()}
                  </div>
                  <StatusBadge status={e.status} />
                </div>
              </div>
            ))}
          {submittedEntries.length === 0 && (
            <EmptyState
              icon="✅"
              title="All clear!"
              message="No entries pending review."
            />
          )}
        </div>
        <div className="card">
          <div className="card-header">
            <span className="card-title">Category Breakdown</span>
          </div>
          {chapterBreakdown.length === 0 ? (
            <EmptyState
              icon="📭"
              title="No entries yet"
              message="Category breakdown appears once activities are submitted."
            />
          ) : (
            chapterBreakdown.map(([name, cnt], i) => {
              const pct = entries.length
                ? Math.round((cnt / entries.length) * 100)
                : 0;
              const colors = [
                "var(--blue)",
                "var(--green)",
                "var(--accent)",
                "var(--purple)",
                "var(--yellow)",
              ];
              return (
                <div key={name} style={{ marginBottom: 12 }}>
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      fontSize: 12,
                      color: "var(--text2)",
                      marginBottom: 4,
                    }}
                  >
                    <span style={{ color: "var(--text)" }}>{name}</span>
                    <span>{cnt} entries</span>
                  </div>
                  <div
                    style={{
                      height: 5,
                      background: "rgba(255,255,255,.07)",
                      borderRadius: 3,
                      overflow: "hidden",
                    }}
                  >
                    <div
                      style={{
                        width: `${pct}%`,
                        height: "100%",
                        background: colors[i % colors.length],
                        borderRadius: 3,
                        transition: "width .4s",
                      }}
                    />
                  </div>
                </div>
              );
            })
          )}
        </div>
        <div
          className="card"
          style={{ marginTop: 16, borderLeft: "3px solid var(--accent)" }}
        >
          <div className="card-header">
            <span className="card-title">🏗️ Project Builder</span>
            <a
              href="/projects"
              style={{
                fontSize: 12,
                color: "var(--accent)",
                textDecoration: "none",
              }}
            >
              Go to Projects →
            </a>
          </div>
          <p style={{ fontSize: 13, color: "var(--text2)", lineHeight: 1.6 }}>
            Create and manage custom projects with chapters, work items, and
            measurement fields. Field engineers follow your project structure
            when submitting e-MB entries.
          </p>
        </div>
      </div>
    </div>
  );
}
