import { useMemo } from 'react';
import { useQuery, useMutation } from '@apollo/client';

/**
 * Query with component-chosen fields (keep `fields` stable — use PRESETS or a module constant).
 *
 * @example
 * useApiQuery(Q.activities.list, {
 *   fields: PRESETS.activityTable,
 *   variables: { page: 1, limit: 20 },
 * });
 */
export function useApiQuery(
  queryFn,
  { fields, queryOptions, variables, skip, ...apolloOptions } = {},
) {
  const document = useMemo(
    () => queryFn(fields, queryOptions),
    [queryFn, fields, queryOptions],
  );
  return useQuery(document, { variables, skip: skip ?? !fields, ...apolloOptions });
}

/**
 * Mutation with component-chosen return fields.
 *
 * @example
 * useApiMutation(M.activities.updateStatus, { fields: '_id status' });
 */
export function useApiMutation(mutationFn, { fields, ...apolloOptions } = {}) {
  const document = useMemo(() => mutationFn(fields), [mutationFn, fields]);
  return useMutation(document, apolloOptions);
}
